export const controlCenterCss = String.raw`
:root{color-scheme:dark;--bg:#081018;--panel:#0d1722;--line:#233244;--text:#f4f7fb;--muted:#8fa1b5;--good:#48d597;--warn:#f5bc5b;--danger:#ff7d88;--shadow:0 20px 60px rgba(0,0,0,.28)}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 80% 0,#152b48 0,transparent 32%),var(--bg);color:var(--text);font:14px/1.45 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}button,input,select,textarea{font:inherit}.shell{min-height:100vh;display:grid;grid-template-columns:248px 1fr}.sidebar{position:sticky;top:0;height:100vh;padding:24px 16px;border-right:1px solid var(--line);background:rgba(8,16,24,.86);backdrop-filter:blur(18px)}.brand{display:flex;gap:12px;align-items:center;padding:4px 8px 26px}.mark{width:38px;height:38px;border-radius:12px;background:linear-gradient(135deg,#9a8cff,#579cff 52%,#51d6b5);box-shadow:0 8px 28px rgba(104,144,255,.3)}.brand strong{display:block;font-size:15px}.brand span{color:var(--muted);font-size:12px}.nav{display:grid;gap:5px}.nav button{border:0;text-align:left;padding:10px 12px;border-radius:10px;background:transparent;color:var(--muted);cursor:pointer}.nav button:hover,.nav button.active{background:#152334;color:#fff}.nav small{float:right;color:#60748a}.side-foot{position:absolute;bottom:20px;left:16px;right:16px;padding:12px;border:1px solid var(--line);border-radius:12px;color:var(--muted);font-size:12px}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--good);box-shadow:0 0 0 5px rgba(72,213,151,.1);margin-right:8px}.main{padding:30px 34px 60px;max-width:1600px;width:100%}.topbar{display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:26px}.eyebrow{color:#82a1c4;font-size:12px;text-transform:uppercase;letter-spacing:.12em}.topbar h1{font-size:28px;margin:4px 0 6px;letter-spacing:-.03em}.muted{color:var(--muted)}.actions{display:flex;gap:10px}.btn{border:1px solid var(--line);background:#132132;color:#fff;padding:9px 13px;border-radius:10px;cursor:pointer}.btn:hover{border-color:#425a73}.btn.primary{background:linear-gradient(135deg,#6e7df6,#5f9df7);border:0}.btn.danger{color:#ff98a1}.grid{display:grid;gap:16px}.metrics{grid-template-columns:repeat(4,minmax(0,1fr));margin-bottom:16px}.card{border:1px solid var(--line);border-radius:16px;background:linear-gradient(180deg,rgba(17,29,41,.92),rgba(12,22,32,.92));box-shadow:var(--shadow)}.metric{padding:18px}.metric .label{color:var(--muted);font-size:12px}.metric .value{font-size:28px;font-weight:700;letter-spacing:-.04em;margin-top:8px}.metric .sub{font-size:12px;color:#7290ad;margin-top:4px}.split{grid-template-columns:1.4fr 1fr}.section{padding:20px}.section-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:15px}.section h2{font-size:15px;margin:0}.stack{display:grid;gap:10px}.module,.tool{display:grid;grid-template-columns:1fr auto;gap:14px;align-items:center;padding:13px 14px;border:1px solid #1d2c3d;border-radius:12px;background:#0c1621}.module strong,.tool strong{display:block}.small{font-size:12px;color:var(--muted)}.badge{font-size:11px;padding:5px 8px;border-radius:99px;border:1px solid #304256;color:#a9bdd1}.badge.available{border-color:rgba(72,213,151,.35);color:#72e4af;background:rgba(72,213,151,.08)}.badge.in_development{border-color:rgba(245,188,91,.35);color:#f5c975;background:rgba(245,188,91,.08)}.badge.danger{border-color:rgba(255,125,136,.35);color:#ff9ca4;background:rgba(255,125,136,.08)}.table-wrap{overflow:auto}.table{width:100%;border-collapse:collapse}.table th,.table td{text-align:left;padding:13px 12px;border-bottom:1px solid #1b2a39;white-space:nowrap}.table th{font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:#6f849a}.table td{color:#d7e1ec}.empty{padding:38px;text-align:center;color:var(--muted);border:1px dashed #2a3c4e;border-radius:13px}.panel{display:none}.panel.active{display:block}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.field{display:grid;gap:6px}.field.full{grid-column:1/-1}.field label{color:#9db0c4;font-size:12px}.field input,.field select,.field textarea{width:100%;border:1px solid #2b3d50;background:#0a141e;color:#fff;border-radius:10px;padding:10px 11px;outline:0}.field textarea{min-height:108px;resize:vertical}.field input:focus,.field select:focus,.field textarea:focus{border-color:#6688ed}.cap-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.cap{display:flex;gap:8px;align-items:center;padding:9px 10px;border:1px solid #26394c;border-radius:10px;background:#0a141e}.cap input{width:auto}.modal{display:none;position:fixed;inset:0;background:rgba(2,7,12,.72);align-items:center;justify-content:center;padding:20px;z-index:5}.modal.open{display:flex}.modal-card{width:min(680px,100%);padding:20px}.modal-title{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.modal-title h2{margin:0;font-size:18px}.notice{padding:13px 14px;border:1px solid #2a3d53;border-radius:11px;color:#a9bdd1;background:#0d1824}.notice.warn{border-color:rgba(245,188,91,.3);color:#e8c887}.kv{display:grid;grid-template-columns:180px 1fr;padding:11px 0;border-bottom:1px solid #1b2a39}.kv span:first-child{color:var(--muted)}.toast{position:fixed;right:24px;bottom:24px;background:#132132;border:1px solid #35506a;padding:12px 14px;border-radius:11px;box-shadow:var(--shadow);display:none;z-index:8}.toast.show{display:block}.preview-shot{width:100%;max-height:520px;object-fit:contain;border:1px solid #26394c;border-radius:12px;background:#071019}.evidence{max-height:260px;overflow:auto;white-space:pre-wrap;padding:12px;border:1px solid #26394c;border-radius:10px;background:#08121c;color:#bed0e2;font:12px/1.5 ui-monospace,SFMono-Regular,Consolas,monospace}@media(max-width:1050px){.shell{grid-template-columns:76px 1fr}.brand div,.nav span,.nav small,.side-foot{display:none}.sidebar{padding:20px 10px}.nav button{text-align:center}.metrics{grid-template-columns:repeat(2,1fr)}.split{grid-template-columns:1fr}}@media(max-width:680px){.shell{display:block}.sidebar{position:static;height:auto;border-right:0;border-bottom:1px solid var(--line)}.brand{padding-bottom:12px}.brand div{display:block}.nav{grid-template-columns:repeat(3,1fr)}.nav span{display:inline}.main{padding:22px 16px}.metrics{grid-template-columns:1fr 1fr}.topbar{gap:12px}.actions{flex-direction:column}.form-grid,.cap-grid{grid-template-columns:1fr}}
`;

export const controlCenterJs = String.raw`
const state={overview:null,projects:[],settings:null,tools:[],policies:[],sessions:[],jobs:[],jobProjectId:'',gitProjectId:'',gitStatus:null,gitLog:[],gitBranches:[],processProjectId:'',processProfiles:[],processes:[],previewProjectId:'',previewProfiles:[],previews:[],previewReview:null,tunnel:null,tunnelSetup:null,tunnelAutoStart:null,tunnelDoctor:'',auditEvents:[],auditProjectId:'',usage:null,usageProjectId:'',usageDays:30,editId:null};
const $=(q)=>document.querySelector(q); const $$=(q)=>[...document.querySelectorAll(q)];
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));}
async function api(url,options={}){const r=await fetch(url,{headers:{'content-type':'application/json',...(options.headers||{})},...options});const body=await r.json().catch(()=>({}));if(!r.ok)throw new Error(body?.error?.message||('HTTP '+r.status));return body;}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2600);}
function badge(s){return '<span class="badge '+esc(s)+'">'+esc(String(s).replace('_',' '))+'</span>';}
function setPanel(id){$$('.panel').forEach(x=>x.classList.toggle('active',x.id==='panel-'+id));$$('.nav button').forEach(x=>x.classList.toggle('active',x.dataset.panel===id));const titles={overview:['Operations overview','Live control-plane status and capability surface'],projects:['Projects','Registered workspace roots and lifecycle'],mcp:['MCP & Tools','Protocol endpoint and exposed tool catalog'],permissions:['Permissions','Human-issued capability grants and temporary sessions'],policies:['Policies','Deterministic server-side deny enforcement'],jobs:['AI Jobs','Persistent coding objectives and agent state'],workflows:['Workflow Runs','Iteration, verification and review evidence across coding jobs'],git:['Git','Local repository state, branches and checkpoint history'],processes:['Processes','Runtime-owned long-running project processes and logs'],browser:['Browser / Preview','Loopback previews and browser QA evidence'],tunnel:['Secure MCP Tunnel','ChatGPT Web connectivity through the OpenAI-managed local tunnel'],audit:['Audit Log','Persistent MCP and Control Center activity evidence'],usage:['Usage','LLM token accounting and MCP request visibility'],settings:['Settings','Effective runtime configuration']};$('#title').textContent=titles[id][0];$('#subtitle').textContent=titles[id][1];$('#addProject').style.display=id==='projects'?'inline-block':'none';}
function renderOverview(){const o=state.overview;if(!o)return;$('#metrics').innerHTML=[['Projects',o.counts.projects,'registered'],['Active projects',o.counts.activeProjects,'enabled'],['MCP tools',o.counts.tools,'exposed'],['Permission sessions',o.counts.permissionSessions,'active now']].map(x=>'<div class="card metric"><div class="label">'+x[0]+'</div><div class="value">'+x[1]+'</div><div class="sub">'+x[2]+'</div></div>').join('');$('#modules').innerHTML=o.modules.map(m=>'<div class="module"><div><strong>'+esc(m.label)+'</strong><div class="small">'+esc(m.id)+'</div></div>'+badge(m.state)+'</div>').join('');$('#runtime').innerHTML=Object.entries(o.runtime).map(([k,v])=>'<div class="kv"><span>'+esc(k)+'</span><strong>'+esc(v)+'</strong></div>').join('');}
function renderProjects(){const el=$('#projectsBody');if(!state.projects.length){el.innerHTML='<tr><td colspan="6"><div class="empty">No projects registered yet. Add the first project to configure the control plane.</div></td></tr>';return;}el.innerHTML=state.projects.map(p=>'<tr><td><strong>'+esc(p.name)+'</strong><div class="small">'+esc(p.alias)+'</div></td><td>'+esc(p.rootPath)+'</td><td>'+badge(p.status==='active'?'available':'planned')+'</td><td>'+esc(p.brainStatus)+'</td><td>'+esc(p.defaultBranch||'—')+'</td><td><button class="btn" data-edit="'+esc(p.id)+'">Edit</button> <button class="btn danger" data-delete="'+esc(p.id)+'">Remove</button></td></tr>').join('');$$('[data-edit]').forEach(b=>b.onclick=()=>openEdit(b.dataset.edit));$$('[data-delete]').forEach(b=>b.onclick=()=>removeProject(b.dataset.delete));}
function renderTools(){const o=state.overview;$('#mcpRuntime').innerHTML='<div class="kv"><span>Protocol</span><strong>'+esc(o.runtime.protocol)+'</strong></div><div class="kv"><span>HTTP endpoint</span><strong>http://'+esc(o.runtime.host)+':'+esc(o.runtime.port)+esc(o.runtime.endpoint)+'</strong></div><div class="kv"><span>Transport</span><strong>'+esc(o.runtime.transport)+'</strong></div>';$('#tools').innerHTML=state.tools.map(t=>'<div class="tool"><div><strong>'+esc(t.name)+'</strong><div class="small">'+esc(t.description)+'</div></div>'+badge(t.state)+'</div>').join('');}
function projectOptions(includeGlobal=false){return (includeGlobal?'<option value="">Global</option>':'')+state.projects.map(p=>'<option value="'+esc(p.id)+'">'+esc(p.name)+' ('+esc(p.alias)+')</option>').join('');}
async function loadSessions(){const id=$('#sessionProject').value;if(!id){state.sessions=[];renderSessions();return;}const body=await api('/api/projects/'+id+'/permission-sessions');state.sessions=body.permissionSessions;renderSessions();}
function renderPermissions(){const opts=projectOptions(false);$('#sessionProject').innerHTML=opts;$('#policyProject').innerHTML=projectOptions(true);const caps=state.settings?.authorization?.capabilities||[];$('#capabilities').innerHTML=caps.map((c,i)=>'<label class="cap"><input type="checkbox" value="'+esc(c)+'" '+(i<3?'checked':'')+'> '+esc(c)+'</label>').join('');loadSessions().catch(e=>toast(e.message));}
function renderSessions(){const el=$('#sessionsBody');if(!state.sessions.length){el.innerHTML='<tr><td colspan="5"><div class="empty">No permission sessions for this project.</div></td></tr>';return;}el.innerHTML=state.sessions.map(s=>{const noExpiry=s.expiresAt.startsWith('9999-');const active=!s.revokedAt&&(noExpiry||Date.parse(s.expiresAt)>Date.now());return '<tr><td><strong>'+esc(s.principalId)+'</strong><div class="small">'+esc(s.id)+'</div></td><td>'+esc(s.capabilities.join(', '))+'</td><td>'+esc(noExpiry?'No expiry':new Date(s.expiresAt).toLocaleString())+'</td><td>'+badge(active?'available':'planned')+'</td><td>'+(active?'<button class="btn danger" data-revoke="'+esc(s.id)+'">Revoke</button>':'—')+'</td></tr>';}).join('');$$('[data-revoke]').forEach(b=>b.onclick=()=>revokeSession(b.dataset.revoke));}
async function createSession(e){e.preventDefault();const projectId=$('#sessionProject').value;if(!projectId)return toast('Select a project');const capabilities=$$('#capabilities input:checked').map(x=>x.value);try{await api('/api/projects/'+projectId+'/permission-sessions',{method:'POST',body:JSON.stringify({principalId:$('#principalId').value,ttlSeconds:Number($('#sessionTtl').value),capabilities,note:$('#sessionNote').value||null})});await refresh();toast('Permission session created');}catch(e){toast(e.message);}}
async function revokeSession(id){if(!confirm('Revoke this permission session immediately?'))return;try{await api('/api/permission-sessions/'+id+'/revoke',{method:'POST',body:'{}'});await loadSessions();await refreshOverview();toast('Permission session revoked');}catch(e){toast(e.message);}}
function renderPolicies(){const el=$('#policiesBody');if(!state.policies.length){el.innerHTML='<tr><td colspan="6"><div class="empty">No policies. Session grants are still required by default.</div></td></tr>';return;}el.innerHTML=state.policies.map(p=>{const project=state.projects.find(x=>x.id===p.projectId);return '<tr><td><strong>'+esc(p.name)+'</strong><div class="small">'+esc(p.reason||'')+'</div></td><td>'+esc(project?project.alias:'Global')+'</td><td>'+esc(p.capability)+'</td><td>'+badge(p.effect==='deny'?'danger':'available')+'</td><td>'+esc(p.enabled?'Enabled':'Disabled')+'</td><td><button class="btn" data-toggle-policy="'+esc(p.id)+'" data-enabled="'+esc(p.enabled)+'">'+(p.enabled?'Disable':'Enable')+'</button> <button class="btn danger" data-delete-policy="'+esc(p.id)+'">Delete</button></td></tr>';}).join('');$$('[data-toggle-policy]').forEach(b=>b.onclick=()=>togglePolicy(b.dataset.togglePolicy,b.dataset.enabled==='true'));$$('[data-delete-policy]').forEach(b=>b.onclick=()=>deletePolicy(b.dataset.deletePolicy));}
async function createPolicy(e){e.preventDefault();try{await api('/api/policies',{method:'POST',body:JSON.stringify({name:$('#policyName').value,projectId:$('#policyProject').value||null,capability:$('#policyCapability').value,effect:$('#policyEffect').value,enabled:true,reason:$('#policyReason').value||null})});$('#policyName').value='';$('#policyReason').value='';await refresh();toast('Policy created');}catch(e){toast(e.message);}}
async function togglePolicy(id,enabled){try{await api('/api/policies/'+id,{method:'PUT',body:JSON.stringify({enabled:!enabled})});await refresh();toast('Policy updated');}catch(e){toast(e.message);}}
async function deletePolicy(id){if(!confirm('Delete this policy?'))return;try{await api('/api/policies/'+id,{method:'DELETE'});await refresh();toast('Policy deleted');}catch(e){toast(e.message);}}
function jobBadge(status){const cls=status==='completed'?'available':(['failed','stopped'].includes(status)?'danger':(['running','awaiting_fix','awaiting_review'].includes(status)?'in_development':'planned'));return '<span class="badge '+cls+'">'+esc(String(status).replaceAll('_',' '))+'</span>';}
function renderJobSelectors(){const options=projectOptions(false);if(!state.projects.some(p=>p.id===state.jobProjectId))state.jobProjectId=state.projects[0]?.id||'';$('#jobProject').innerHTML=options;$('#workflowProject').innerHTML=options;if(state.jobProjectId){$('#jobProject').value=state.jobProjectId;$('#workflowProject').value=state.jobProjectId;}}
async function loadJobs(){if(!state.jobProjectId){state.jobs=[];renderJobs();renderWorkflows();return;}const body=await api('/api/projects/'+state.jobProjectId+'/ai-jobs');state.jobs=body.jobs||[];renderJobs();renderWorkflows();}
function renderJobs(){const el=$('#jobsBody');if(!state.jobs.length){el.innerHTML='<tr><td colspan="6"><div class="empty">No persistent AI jobs for this project.</div></td></tr>';return;}const terminal=new Set(['completed','stopped','failed','cancelled']);el.innerHTML=state.jobs.map(j=>'<tr><td><strong>'+esc(j.objective)+'</strong><div class="small">'+esc(j.id)+'</div></td><td>'+jobBadge(j.status)+'</td><td>'+esc(j.iteration)+' / '+esc(j.maxIterations)+'</td><td>'+esc((j.evidence||[]).length)+'</td><td>'+esc(new Date(j.updatedAt).toLocaleString())+'</td><td>'+(terminal.has(j.status)?'—':'<button class="btn danger" data-cancel-job="'+esc(j.id)+'">Cancel</button>')+'</td></tr>').join('');$$('[data-cancel-job]').forEach(b=>b.onclick=()=>cancelJob(b.dataset.cancelJob));}
function renderWorkflows(){const counts={queued:0,running:0,attention:0,done:0};state.jobs.forEach(j=>{if(j.status==='queued')counts.queued++;else if(j.status==='running')counts.running++;else if(['awaiting_fix','awaiting_review'].includes(j.status))counts.attention++;else counts.done++;});$('#workflowMetrics').innerHTML=[['Queued',counts.queued],['Running',counts.running],['Needs review/fix',counts.attention],['Terminal',counts.done]].map(x=>'<div class="card metric"><div class="label">'+x[0]+'</div><div class="value">'+x[1]+'</div></div>').join('');const el=$('#workflowBody');if(!state.jobs.length){el.innerHTML='<tr><td colspan="6"><div class="empty">No workflow runs for this project yet.</div></td></tr>';return;}el.innerHTML=state.jobs.map(j=>{const latest=(j.evidence||[]).at(-1)||{};return '<tr><td><strong>'+esc(j.objective)+'</strong></td><td>'+jobBadge(j.status)+'</td><td>'+esc(j.iteration)+' / '+esc(j.maxIterations)+'</td><td>'+esc(latest.nextAction||latest.state||'—')+'</td><td>'+esc(j.reviewSummary||'—')+'</td><td>'+esc(new Date(j.updatedAt).toLocaleString())+'</td></tr>';}).join('');}
async function createJob(e){e.preventDefault();if(!state.jobProjectId)return toast('Select a project');try{await api('/api/projects/'+state.jobProjectId+'/ai-jobs',{method:'POST',body:JSON.stringify({objective:$('#jobObjective').value,maxIterations:Number($('#jobMaxIterations').value)})});$('#jobObjective').value='';await loadJobs();toast('AI job created');}catch(e){toast(e.message);}}
async function cancelJob(id){if(!confirm('Cancel this AI job?'))return;try{await api('/api/ai-jobs/'+id+'/cancel',{method:'POST',body:'{}'});await loadJobs();toast('AI job cancelled');}catch(e){toast(e.message);}}
function renderBridgeSelectors(){const opts=projectOptions(false);if(!state.projects.some(p=>p.id===state.gitProjectId))state.gitProjectId=state.projects[0]?.id||'';if(!state.projects.some(p=>p.id===state.processProjectId))state.processProjectId=state.projects[0]?.id||'';$('#gitProject').innerHTML=opts;$('#processProject').innerHTML=opts;if(state.gitProjectId)$('#gitProject').value=state.gitProjectId;if(state.processProjectId)$('#processProject').value=state.processProjectId;}
async function loadGit(){if(!state.gitProjectId){state.gitStatus=null;state.gitLog=[];state.gitBranches=[];renderGit();return;}const [status,log,branches]=await Promise.all([api('/api/projects/'+state.gitProjectId+'/git/status'),api('/api/projects/'+state.gitProjectId+'/git/log?limit=20'),api('/api/projects/'+state.gitProjectId+'/git/branches')]);state.gitStatus=status.git;state.gitLog=log.gitLog?.commits||[];state.gitBranches=branches.gitBranches?.branches||[];renderGit();}
function renderGit(){const s=state.gitStatus;const summary=$('#gitSummary');const commits=$('#gitCommitsBody');const branches=$('#gitBranchesBody');if(!s){summary.innerHTML='<div class="empty">Select a Git project.</div>';commits.innerHTML='<tr><td colspan="4"><div class="empty">No Git history loaded.</div></td></tr>';branches.innerHTML='<tr><td colspan="4"><div class="empty">No branches loaded.</div></td></tr>';return;}summary.innerHTML='<div class="kv"><span>Branch</span><strong>'+esc(s.branch||'(detached)')+'</strong></div><div class="kv"><span>HEAD</span><strong>'+esc((s.head||'').slice(0,12)||'none')+'</strong></div><div class="kv"><span>Upstream</span><strong>'+esc(s.upstream||'none')+'</strong></div><div class="kv"><span>Ahead / Behind</span><strong>'+esc(s.ahead)+' / '+esc(s.behind)+'</strong></div><div class="kv"><span>Working tree</span><strong>'+esc(s.clean?'clean':(s.entries||[]).length+' changed path(s)')+'</strong></div>';commits.innerHTML=state.gitLog.length?state.gitLog.map(c=>'<tr><td><strong>'+esc(c.subject)+'</strong></td><td>'+esc(c.hash.slice(0,10))+'</td><td>'+esc(c.authorName)+'</td><td>'+esc(new Date(c.authoredAt).toLocaleString())+'</td></tr>').join(''):'<tr><td colspan="4"><div class="empty">No commits.</div></td></tr>';branches.innerHTML=state.gitBranches.length?state.gitBranches.map(b=>'<tr><td><strong>'+esc(b.name)+'</strong></td><td>'+esc(b.current?'current':'')+'</td><td>'+esc(b.commit.slice(0,10))+'</td><td>'+esc(b.upstream||'none')+'</td></tr>').join(''):'<tr><td colspan="4"><div class="empty">No local branches.</div></td></tr>';}
async function loadProcesses(){if(!state.processProjectId){state.processProfiles=[];state.processes=[];renderProcessProfiles();renderProcesses();return;}const [profiles,processes]=await Promise.all([api('/api/projects/'+state.processProjectId+'/process-profiles'),api('/api/projects/'+state.processProjectId+'/processes')]);state.processProfiles=profiles.processProfiles||[];state.processes=processes.processes||[];renderProcessProfiles();renderProcesses();}
function renderProcessProfiles(){const select=$('#processProfile');select.innerHTML=state.processProfiles.map(p=>'<option value="'+esc(p.id)+'">'+esc(p.label)+'</option>').join('');$('#startProcess').disabled=state.processProfiles.length===0;$('#processProfileHint').textContent=state.processProfiles.length?state.processProfiles.length+' managed profile(s) discovered':'No dev/start/serve/preview/storybook/watch profile found';}
function renderProcesses(){const el=$('#processesBody');if(!state.processes.length){el.innerHTML='<tr><td colspan="7"><div class="empty">No managed process sessions in this runtime.</div></td></tr>';return;}el.innerHTML=state.processes.map(p=>'<tr><td><strong>'+esc(p.profileId)+'</strong><div class="small">'+esc(p.id)+'</div></td><td>'+esc(p.pid??'-')+'</td><td>'+badge(p.state==='running'?'available':(p.state==='failed'?'danger':'planned'))+'</td><td>'+esc(new Date(p.startedAt).toLocaleString())+'</td><td>'+esc(p.exitCode??'-')+'</td><td><div class="evidence" style="max-width:520px;max-height:120px">'+esc(((p.stdout||'')+'\n'+(p.stderr||'')).trim().slice(-4000))+'</div></td><td>'+(p.state==='running'?'<button class="btn danger" data-stop-process="'+esc(p.id)+'">Stop</button>':'-')+'</td></tr>').join('');$$('[data-stop-process]').forEach(b=>b.onclick=()=>stopManagedProcess(b.dataset.stopProcess));}
async function startManagedProcess(){if(!state.processProjectId)return toast('Select a project');const profileId=$('#processProfile').value;if(!profileId)return toast('No managed process profile available');try{await api('/api/projects/'+state.processProjectId+'/processes',{method:'POST',body:JSON.stringify({profileId})});await loadProcesses();toast('Managed process started');}catch(e){toast(e.message);}}
async function stopManagedProcess(id){try{await api('/api/projects/'+state.processProjectId+'/processes/'+id+'/stop',{method:'POST',body:'{}'});await loadProcesses();toast('Managed process stopped');}catch(e){toast(e.message);}}
function renderPreviewSelector(){if(!state.projects.some(p=>p.id===state.previewProjectId))state.previewProjectId=state.projects[0]?.id||'';$('#previewProject').innerHTML=projectOptions(false);if(state.previewProjectId)$('#previewProject').value=state.previewProjectId;}
async function loadPreviews(){if(!state.previewProjectId){state.previewProfiles=[];state.previews=[];renderPreviewProfiles();renderPreviews();return;}const [profiles,previews]=await Promise.all([api('/api/projects/'+state.previewProjectId+'/preview-profiles'),api('/api/projects/'+state.previewProjectId+'/previews')]);state.previewProfiles=profiles.previewProfiles||[];state.previews=previews.previews||[];renderPreviewProfiles();renderPreviews();}
function renderPreviewProfiles(){const select=$('#previewProfile');select.innerHTML=state.previewProfiles.map(p=>'<option value="'+esc(p.id)+'">'+esc(p.label)+' · '+esc(p.kind)+'</option>').join('');$('#startPreview').disabled=state.previewProfiles.length===0;$('#previewProfileHint').textContent=state.previewProfiles.length?state.previewProfiles.length+' profile(s) discovered from the project':'No supported preview profile found';}
function renderPreviews(){const el=$('#previewsBody');if(!state.previews.length){el.innerHTML='<tr><td colspan="7"><div class="empty">No preview sessions in this runtime.</div></td></tr>';return;}el.innerHTML=state.previews.map(p=>'<tr><td><strong>'+esc(p.framework)+'</strong><div class="small">'+esc(p.profileId)+'</div></td><td>'+esc(p.kind)+'</td><td><span class="badge '+(p.state==='running'?'available':(p.state==='failed'?'danger':'planned'))+'">'+esc(p.state)+'</span></td><td>'+esc(p.url)+'</td><td>'+esc(p.port)+'</td><td>'+esc(new Date(p.startedAt).toLocaleString())+'</td><td>'+(p.state==='running'?'<button class="btn" data-review-preview="'+esc(p.id)+'">Review</button> <button class="btn danger" data-stop-preview="'+esc(p.id)+'">Stop</button>':'—')+'</td></tr>').join('');$$('[data-review-preview]').forEach(b=>b.onclick=()=>reviewPreview(b.dataset.reviewPreview));$$('[data-stop-preview]').forEach(b=>b.onclick=()=>stopPreview(b.dataset.stopPreview));}
function renderPreviewReview(){const el=$('#previewEvidence');const r=state.previewReview;if(!r){el.innerHTML='<div class="empty">Run Browser Review on a live preview to capture DOM, console, network and screenshot evidence.</div>';return;}const issueCount=(r.pageErrors||[]).length+(r.failedRequests||[]).length;el.innerHTML='<div class="grid split"><div><div class="kv"><span>Title</span><strong>'+esc(r.title||'—')+'</strong></div><div class="kv"><span>HTTP</span><strong>'+esc(r.httpStatus??'—')+'</strong></div><div class="kv"><span>Interactive</span><strong>'+esc((r.interactive||[]).length)+'</strong></div><div class="kv"><span>Blocked egress</span><strong>'+esc((r.blockedRequests||[]).length)+'</strong></div><div class="kv"><span>Errors</span><strong>'+esc(issueCount)+'</strong></div><div class="evidence" style="margin-top:12px">'+esc((r.bodyText||'').slice(0,6000))+'</div></div><div>'+(r.screenshotBase64?'<img class="preview-shot" alt="Browser review screenshot" src="data:image/jpeg;base64,'+r.screenshotBase64+'">':'<div class="empty">No screenshot returned</div>')+'</div></div>';}
async function startPreview(){if(!state.previewProjectId)return toast('Select a project');const profileId=$('#previewProfile').value;if(!profileId)return toast('No preview profile available');try{await api('/api/projects/'+state.previewProjectId+'/previews',{method:'POST',body:JSON.stringify({profileId})});await loadPreviews();toast('Preview started');}catch(e){toast(e.message);}}
async function stopPreview(id){try{await api('/api/previews/'+id+'/stop',{method:'POST',body:'{}'});await loadPreviews();toast('Preview stopped');}catch(e){toast(e.message);}}
async function reviewPreview(id){try{const path=$('#previewPath').value||'/';const body=await api('/api/previews/'+id+'/review',{method:'POST',body:JSON.stringify({path,actions:[]})});state.previewReview=body.review;renderPreviewReview();toast('Browser review captured');}catch(e){toast(e.message);}}
function tunnelBadge(stateName){const cls=stateName==='ready'?'available':(['client_missing','local_mcp_unavailable'].includes(stateName)?'danger':'in_development');return '<span class="badge '+cls+'">'+esc(String(stateName||'unknown').replaceAll('_',' '))+'</span>';}
function yesNo(value){return value?'Yes':'No';}
async function loadTunnel(){const [body,auto]=await Promise.all([api('/api/tunnel/setup'),api('/api/tunnel/windows-autostart')]);state.tunnel=body.tunnel;state.tunnelSetup=body.setup;state.tunnelAutoStart=auto.autoStart;renderTunnel();renderTunnelSetup();}
function renderTunnelSetup(){const s=state.tunnelSetup;if(!s)return;const id=$('#tunnelSetupId');const auto=$('#tunnelSetupAuto');const stored=$('#tunnelStoredSecret');const win=$('#tunnelWindowsAutoStart');const winStatus=$('#tunnelAutoStartStatus');if(id&&document.activeElement!==id)id.value=s.tunnelId||'';if(auto)auto.checked=Boolean(s.autoConnect);if(stored)stored.textContent=s.runtimeApiKeyConfigured?'Stored securely · '+s.secretProvider:'Not stored yet';if(win)win.checked=Boolean(state.tunnelAutoStart?.enabled);if(win)win.disabled=state.tunnelAutoStart?.supported===false;if(winStatus){const a=state.tunnelAutoStart;winStatus.textContent=!a?'Windows auto-start status loading…':(a.supported?(a.enabled?'Enabled · MCP Coding starts automatically when you sign in':'Disabled · enable to avoid PowerShell after reboot'):'Unavailable on this platform');}}
async function saveTunnelSetup(e){e.preventDefault();const key=$('#tunnelSetupKey').value;const payload={tunnelId:$('#tunnelSetupId').value.trim(),autoConnect:$('#tunnelSetupAuto').checked};if(key.trim())payload.runtimeApiKey=key;const wantWindowsAutoStart=Boolean($('#tunnelWindowsAutoStart')?.checked);try{const body=await api('/api/tunnel/setup',{method:'PUT',body:JSON.stringify(payload)});$('#tunnelSetupKey').value='';state.tunnel=body.tunnel;state.tunnelSetup=body.setup;if(state.tunnelAutoStart?.supported!==false){const startup=await api('/api/tunnel/windows-autostart',{method:'PUT',body:JSON.stringify({enabled:wantWindowsAutoStart})});state.tunnelAutoStart=startup.autoStart;}renderTunnel();renderTunnelSetup();toast('Tunnel setup saved securely');}catch(e){toast(e.message);}}
async function clearTunnelStoredKey(){if(!confirm('Remove the stored Runtime API key from secure local storage?'))return;try{const body=await api('/api/tunnel/runtime-api-key',{method:'DELETE'});state.tunnel=body.tunnel;state.tunnelSetup=body.setup;renderTunnel();renderTunnelSetup();toast('Stored Runtime API key removed');}catch(e){toast(e.message);}}
function renderTunnel(){const t=state.tunnel;const summary=$('#tunnelSummary');const runtime=$('#tunnelRuntime');const doctor=$('#tunnelDoctor');if(!t){summary.innerHTML='<div class="empty">Tunnel status is loading.</div>';runtime.innerHTML='';doctor.textContent=state.tunnelDoctor||'No doctor run yet.';return;}const c=t.configuration||{};const r=t.runtime||{};const b=t.binary||{};const local=t.localMcp||{};summary.innerHTML='<div class="section-head"><div><h2>OpenAI Secure MCP Tunnel</h2><div class="small">ChatGPT Web → OpenAI tunnel → tunnel-client → local MCP</div></div>'+tunnelBadge(t.state)+'</div><div class="kv"><span>tunnel-client</span><strong>'+esc(b.version||'not installed')+'</strong></div><div class="kv"><span>Binary path</span><strong>'+esc(b.path||'—')+'</strong></div><div class="kv"><span>Local MCP target</span><strong>'+esc(c.mcpServerUrl||'—')+'</strong></div><div class="kv"><span>Local MCP ready</span><strong>'+esc(yesNo(local.ready))+(local.httpStatus?' · HTTP '+esc(local.httpStatus):'')+'</strong></div><div class="kv"><span>Tunnel ID configured</span><strong>'+esc(yesNo(c.tunnelIdConfigured))+'</strong></div><div class="kv"><span>Runtime API key configured</span><strong>'+esc(yesNo(c.runtimeApiKeyConfigured))+'</strong></div><div class="kv"><span>Auto-connect</span><strong>'+esc(yesNo(c.autoConnect))+'</strong></div>';runtime.innerHTML='<div class="kv"><span>Managed runtime</span><strong>'+esc(r.known?'known':'not created')+'</strong></div><div class="kv"><span>Process running</span><strong>'+esc(r.processRunning===null?'—':yesNo(r.processRunning))+'</strong></div><div class="kv"><span>Healthy / Ready</span><strong>'+esc((r.healthy===null?'—':yesNo(r.healthy))+' / '+(r.ready===null?'—':yesNo(r.ready)))+'</strong></div><div class="kv"><span>PID</span><strong>'+esc(r.pid??'—')+'</strong></div><div class="kv"><span>Tunnel ID</span><strong>'+esc(r.tunnelIdMasked||'—')+'</strong></div><div class="kv"><span>Health URL</span><strong>'+esc(r.healthUrl||'—')+'</strong></div><div class="kv"><span>Runtime UI</span><strong>'+esc(r.uiUrl||'—')+'</strong></div><div class="kv"><span>Control-plane poll</span><strong>'+esc(r.controlPlanePollHealth??'—')+'</strong></div>';const configured=Boolean(b.installed&&local.ready&&c.tunnelIdConfigured&&c.runtimeApiKeyConfigured);$('#tunnelDoctorBtn').disabled=!configured;$('#tunnelConnectBtn').disabled=!configured||Boolean(r.processRunning&&r.ready);$('#tunnelStopBtn').disabled=!Boolean(r.known&&r.processRunning);doctor.textContent=state.tunnelDoctor||((!c.tunnelIdConfigured||!c.runtimeApiKeyConfigured)?'External activation pending: configure CONTROL_PLANE_TUNNEL_ID and CONTROL_PLANE_API_KEY in the MCP process environment.':'No doctor run yet.');}
async function tunnelAction(action){const button=$('#tunnel'+action[0].toUpperCase()+action.slice(1)+'Btn');if(button)button.disabled=true;try{const body=await api('/api/tunnel/'+action,{method:'POST',body:'{}'});if(action==='doctor')state.tunnelDoctor=body.doctor?.output||'Doctor completed without textual output.';state.tunnel=body.tunnel||body.doctor?.status||state.tunnel;await loadTunnel();toast('Tunnel '+action+' completed');}catch(e){state.tunnelDoctor=String(e.message||e);renderTunnel();toast(e.message);}finally{if(button)button.disabled=false;renderTunnel();}}
function fmtNumber(v){return Number(v||0).toLocaleString();}
function fmtUsd(v){const n=Number(v||0);return '$'+n.toFixed(n<1?4:2);}
function auditStatusBadge(status){const cls=status==='success'?'available':'danger';return '<span class="badge '+cls+'">'+esc(status)+'</span>';}
function tokenVisibilityBadge(visibility){const cls=visibility==='actual'?'available':(visibility==='estimated'?'in_development':'');return '<span class="badge '+cls+'">'+esc(visibility)+'</span>';}
function renderAuditSelectors(){const project=$('#auditProject');if(!project)return;project.innerHTML='<option value="">All projects</option>'+projectOptions(false);if(state.auditProjectId)project.value=state.auditProjectId;}
async function loadAudit(){const params=new URLSearchParams({limit:'200'});const project=$('#auditProject')?.value||state.auditProjectId;const status=$('#auditStatus')?.value||'';const category=$('#auditCategory')?.value?.trim()||'';const query=$('#auditQuery')?.value?.trim()||'';if(project)params.set('project_id',project);if(status)params.set('status',status);if(category)params.set('category',category);if(query)params.set('q',query);const body=await api('/api/audit?'+params.toString());state.auditEvents=body.auditEvents||[];renderAudit();}
function renderAudit(){const el=$('#auditBody');if(!el)return;if(!state.auditEvents.length){el.innerHTML='<tr><td colspan="8"><div class="empty">No audit events match the current filters.</div></td></tr>';return;}el.innerHTML=state.auditEvents.map(e=>{const p=state.projects.find(x=>x.id===e.projectId);return '<tr><td>'+esc(new Date(e.occurredAt).toLocaleString())+'</td><td>'+esc(e.category)+'</td><td><strong>'+esc(e.action)+'</strong></td><td>'+esc(p?.alias||e.projectId||'—')+'</td><td>'+esc(e.actorId||e.actorType||'—')+'</td><td>'+auditStatusBadge(e.status)+'</td><td>'+esc(e.durationMs===null?'—':e.durationMs+' ms')+'</td><td>'+esc(e.errorCode||'—')+'</td></tr>';}).join('');}
function renderUsageSelectors(){const project=$('#usageProject');if(project){project.innerHTML='<option value="">All projects</option>'+projectOptions(false);if(state.usageProjectId)project.value=state.usageProjectId;}const days=$('#usageDays');if(days)days.value=String(state.usageDays);}
async function loadUsage(){const project=$('#usageProject')?.value||state.usageProjectId;const days=Number($('#usageDays')?.value||state.usageDays||30);const params=new URLSearchParams({days:String(days)});if(project)params.set('project_id',project);const body=await api('/api/usage?'+params.toString());state.usage=body.usage;state.usageDays=days;renderUsage();}
function renderUsage(){const u=state.usage;if(!u)return;const t=u.totals||{};$('#usageMetrics').innerHTML=[['Known LLM tokens',fmtNumber(t.total_tokens),'actual + explicitly estimated'],['Input tokens',fmtNumber(t.input_tokens),'known usage only'],['Output tokens',fmtNumber(t.output_tokens),'known usage only'],['LLM requests',fmtNumber(t.llm_requests),'provider-reported'],['MCP tool calls',fmtNumber(t.mcp_tool_calls),'ChatGPT/tool activity'],['Token visibility gaps',fmtNumber(t.unavailable_token_requests),'requests without token metadata'],['Estimated cost',fmtUsd(t.estimated_cost_usd),'when a provider adapter supplies cost']].map(x=>'<div class="card metric"><div class="label">'+x[0]+'</div><div class="value">'+x[1]+'</div><div class="sub">'+x[2]+'</div></div>').join('');$('#usageVisibility').textContent=u.tokenVisibility?.explanation||'';const models=$('#usageModelsBody');models.innerHTML=(u.byModel||[]).length?(u.byModel||[]).map(m=>'<tr><td>'+esc(m.provider)+'</td><td><strong>'+esc(m.model)+'</strong></td><td>'+fmtNumber(m.requests)+'</td><td>'+fmtNumber(m.total_tokens)+'</td><td>'+fmtUsd(m.estimated_cost_usd)+'</td></tr>').join(''):'<tr><td colspan="5"><div class="empty">No provider-reported LLM usage yet.</div></td></tr>';const daily=$('#usageDailyBody');daily.innerHTML=(u.daily||[]).length?(u.daily||[]).map(d=>'<tr><td>'+esc(d.day)+'</td><td>'+fmtNumber(d.requests)+'</td><td>'+fmtNumber(d.tool_calls)+'</td><td>'+fmtNumber(d.total_tokens)+'</td></tr>').join(''):'<tr><td colspan="4"><div class="empty">No usage events in this window.</div></td></tr>';const recent=$('#usageRecentBody');recent.innerHTML=(u.recent||[]).length?(u.recent||[]).map(e=>'<tr><td>'+esc(new Date(e.occurredAt).toLocaleString())+'</td><td>'+esc(e.source)+'</td><td>'+esc(e.actorId||e.actorType||'—')+'</td><td>'+esc(e.provider||'—')+'</td><td>'+esc(e.model||'—')+'</td><td>'+esc(e.operation)+'</td><td>'+tokenVisibilityBadge(e.tokenVisibility)+'</td><td>'+esc(e.totalTokens===null?'—':fmtNumber(e.totalTokens))+'</td></tr>').join(''):'<tr><td colspan="8"><div class="empty">No recent usage ledger events.</div></td></tr>';}
function renderSettings(){const effective=state.settings?.effective||{};$('#settings').innerHTML=Object.entries(effective).map(([k,v])=>'<div class="kv"><span>'+esc(k)+'</span><strong>'+esc(v)+'</strong></div>').join('')+'<div class="notice" style="margin-top:14px">'+esc(state.settings?.authorization?.model||'')+'</div><div class="notice" style="margin-top:10px">'+esc(state.settings?.note||'')+'</div>';const caps=state.settings?.authorization?.capabilities||[];$('#policyCapability').innerHTML=caps.map(c=>'<option value="'+esc(c)+'">'+esc(c)+'</option>').join('');}
function openCreate(){state.editId=null;$('#modalHeading').textContent='Register project';$('#projectForm').reset();$('#projectStatusField').style.display='none';$('#projectModal').classList.add('open');}
function openEdit(id){const p=state.projects.find(x=>x.id===id);if(!p)return;state.editId=id;$('#modalHeading').textContent='Edit project';$('#projectName').value=p.name;$('#projectAlias').value=p.alias;$('#projectRoot').value=p.rootPath;$('#projectBranch').value=p.defaultBranch||'';$('#projectRemote').value=p.remoteRepository||'';$('#projectStatus').value=p.status;$('#projectStatusField').style.display='grid';$('#projectModal').classList.add('open');}
function closeModal(){state.editId=null;$('#projectModal').classList.remove('open');}
async function submitProject(e){e.preventDefault();const editing=state.editId;const payload={name:$('#projectName').value,alias:$('#projectAlias').value,rootPath:$('#projectRoot').value,defaultBranch:$('#projectBranch').value||null,remoteRepository:$('#projectRemote').value||null};if(editing)payload.status=$('#projectStatus').value;try{if(editing)await api('/api/projects/'+editing,{method:'PUT',body:JSON.stringify(payload)});else await api('/api/projects',{method:'POST',body:JSON.stringify(payload)});closeModal();await refresh();toast(editing?'Project updated':'Project registered');}catch(e){toast(e.message);}}
async function removeProject(id){const p=state.projects.find(x=>x.id===id);if(!p||!confirm('Remove project "'+p.name+'" from the registry? Files on disk will not be deleted.'))return;try{await api('/api/projects/'+id,{method:'DELETE'});await refresh();toast('Project removed from registry');}catch(e){toast(e.message);}}
async function refreshOverview(){state.overview=await api('/api/control-center/overview');renderOverview();}
async function refresh(){const [overview,projects,settings,tools,policies]=await Promise.all([api('/api/control-center/overview'),api('/api/projects'),api('/api/settings'),api('/api/tools'),api('/api/policies')]);state.overview=overview;state.projects=projects.projects;state.settings=settings;state.tools=tools.tools;state.policies=policies.policies;renderOverview();renderProjects();renderTools();renderSettings();renderPermissions();renderPolicies();renderJobSelectors();renderBridgeSelectors();renderGit();renderProcessProfiles();renderProcesses();renderPreviewSelector();renderPreviewReview();renderAuditSelectors();renderUsageSelectors();loadJobs().catch(e=>{state.jobs=[];renderJobs();renderWorkflows();toast(e.message);});loadPreviews().catch(e=>{state.previewProfiles=[];state.previews=[];renderPreviewProfiles();renderPreviews();renderPreviewReview();toast(e.message);});loadTunnel().catch(e=>{state.tunnel=null;state.tunnelDoctor=String(e.message||e);renderTunnel();toast(e.message);});loadAudit().catch(e=>{state.auditEvents=[];renderAudit();toast(e.message);});loadUsage().catch(e=>{state.usage=null;toast(e.message);});}
$$('.nav button').forEach(b=>b.onclick=()=>setPanel(b.dataset.panel));$('#refresh').onclick=async()=>{await refresh();toast('Control Center refreshed');};$('#addProject').onclick=openCreate;$('#closeModal').onclick=closeModal;$('#cancelModal').onclick=closeModal;$('#projectForm').onsubmit=submitProject;$('#projectModal').onclick=e=>{if(e.target.id==='projectModal')closeModal();};$('#permissionForm').onsubmit=createSession;$('#sessionProject').onchange=()=>loadSessions().catch(e=>toast(e.message));$('#policyForm').onsubmit=createPolicy;$('#jobForm').onsubmit=createJob;$('#jobProject').onchange=()=>{state.jobProjectId=$('#jobProject').value;$('#workflowProject').value=state.jobProjectId;loadJobs().catch(e=>toast(e.message));};$('#workflowProject').onchange=()=>{state.jobProjectId=$('#workflowProject').value;$('#jobProject').value=state.jobProjectId;loadJobs().catch(e=>toast(e.message));};$('#gitProject').onchange=()=>{state.gitProjectId=$('#gitProject').value;loadGit().catch(e=>toast(e.message));};$('#gitRefresh').onclick=()=>loadGit().then(()=>toast('Git refreshed')).catch(e=>toast(e.message));$('#processProject').onchange=()=>{state.processProjectId=$('#processProject').value;loadProcesses().catch(e=>toast(e.message));};$('#processRefresh').onclick=()=>loadProcesses().then(()=>toast('Processes refreshed')).catch(e=>toast(e.message));$('#startProcess').onclick=()=>startManagedProcess();$('#previewProject').onchange=()=>{state.previewProjectId=$('#previewProject').value;state.previewReview=null;renderPreviewReview();loadPreviews().catch(e=>toast(e.message));};$('#startPreview').onclick=()=>startPreview();$('#tunnelRefresh').onclick=()=>loadTunnel().then(()=>toast('Tunnel status refreshed')).catch(e=>toast(e.message));$('#tunnelSetupForm').onsubmit=saveTunnelSetup;$('#tunnelClearKey').onclick=clearTunnelStoredKey;$('#tunnelDoctorBtn').onclick=()=>tunnelAction('doctor');$('#tunnelConnectBtn').onclick=()=>tunnelAction('connect');$('#tunnelStopBtn').onclick=()=>tunnelAction('disconnect');$('#auditRefresh').onclick=()=>loadAudit().then(()=>toast('Audit refreshed')).catch(e=>toast(e.message));$('#auditProject').onchange=()=>{state.auditProjectId=$('#auditProject').value;loadAudit().catch(e=>toast(e.message));};$('#auditStatus').onchange=()=>loadAudit().catch(e=>toast(e.message));$('#auditCategory').onchange=()=>loadAudit().catch(e=>toast(e.message));$('#auditQuery').onkeydown=e=>{if(e.key==='Enter')loadAudit().catch(err=>toast(err.message));};$('#usageRefresh').onclick=()=>loadUsage().then(()=>toast('Usage refreshed')).catch(e=>toast(e.message));$('#usageProject').onchange=()=>{state.usageProjectId=$('#usageProject').value;loadUsage().catch(e=>toast(e.message));};$('#usageDays').onchange=()=>{state.usageDays=Number($('#usageDays').value);loadUsage().catch(e=>toast(e.message));};setPanel('overview');refresh().catch(e=>toast(e.message));
`;

export const controlCenterHtml = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MCP Coding v2 — Control Center</title><link rel="icon" href="data:,"><link rel="stylesheet" href="/control-center/app.css"></head><body><div class="shell"><aside class="sidebar"><div class="brand"><div class="mark"></div><div><strong>MCP Coding v2</strong><span>Control Center</span></div></div><nav class="nav"><button class="active" data-panel="overview"><span>Overview</span><small>01</small></button><button data-panel="projects"><span>Projects</span><small>02</small></button><button data-panel="mcp"><span>MCP & Tools</span><small>03</small></button><button data-panel="permissions"><span>Permissions</span><small>04</small></button><button data-panel="policies"><span>Policies</span><small>05</small></button><button data-panel="jobs"><span>AI Jobs</span><small>06</small></button><button data-panel="workflows"><span>Workflow Runs</span><small>07</small></button><button data-panel="git"><span>Git</span><small>08</small></button><button data-panel="processes"><span>Processes</span><small>09</small></button><button data-panel="browser"><span>Browser / Preview</span><small>10</small></button><button data-panel="tunnel"><span>Secure MCP Tunnel</span><small>11</small></button><button data-panel="audit"><span>Audit Log</span><small>12</small></button><button data-panel="usage"><span>Usage</span><small>13</small></button><button data-panel="settings"><span>Settings</span><small>14</small></button></nav><div class="side-foot"><span class="dot"></span>Local control plane<br><span style="padding-left:16px">127.0.0.1 only</span></div></aside><main class="main"><header class="topbar"><div><div class="eyebrow">Operations / localhost</div><h1 id="title">Operations overview</h1><div id="subtitle" class="muted">Live control-plane status and capability surface</div></div><div class="actions"><button id="refresh" class="btn">Refresh</button><button id="addProject" class="btn primary" style="display:none">+ Add project</button></div></header><section id="panel-overview" class="panel active"><div id="metrics" class="grid metrics"></div><div class="grid split"><div class="card section"><div class="section-head"><h2>Capability map</h2><span class="small">Real implementation state</span></div><div id="modules" class="stack"></div></div><div class="card section"><div class="section-head"><h2>Runtime</h2><span class="badge available">online</span></div><div id="runtime"></div></div></div></section><section id="panel-projects" class="panel"><div class="card section"><div class="section-head"><h2>Project Registry</h2><span class="small">SQLite-backed • canonical root isolation</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Project</th><th>Root</th><th>Status</th><th>Brain</th><th>Branch</th><th>Actions</th></tr></thead><tbody id="projectsBody"></tbody></table></div></div></section><section id="panel-mcp" class="panel"><div class="grid split"><div class="card section"><div class="section-head"><h2>MCP runtime</h2><span class="badge available">2026-07-28</span></div><div id="mcpRuntime"></div></div><div class="card section"><div class="section-head"><h2>Exposed tools</h2><span class="small">No simulated tools</span></div><div id="tools" class="stack"></div></div></div></section><section id="panel-permissions" class="panel"><div class="grid split"><div class="card section"><div class="section-head"><h2>Issue permission session</h2><span class="badge available">P2-T03</span></div><div class="notice warn" style="margin-bottom:14px">Sessions are project-bound and revocable. Long-lived and no-expiry sessions are intended only for trusted local agents; deny policies still override grants.</div><form id="permissionForm"><div class="form-grid"><div class="field full"><label>Project</label><select id="sessionProject" required></select></div><div class="field"><label>Principal ID</label><input id="principalId" value="local-ai-agent" required></div><div class="field"><label>TTL</label><select id="sessionTtl"><option value="1800">30 minutes</option><option value="3600" selected>1 hour</option><option value="14400">4 hours</option><option value="28800">8 hours</option><option value="86400">24 hours</option><option value="604800">7 days</option><option value="2592000">30 days</option><option value="7776000">90 days</option><option value="12960000">150 days</option><option value="0">No expiry</option></select></div><div class="field full"><label>Capabilities</label><div id="capabilities" class="cap-grid"></div></div><div class="field full"><label>Note</label><input id="sessionNote" placeholder="Why this session is needed"></div></div><div class="actions" style="justify-content:flex-end;margin-top:16px"><button class="btn primary" type="submit">Create session</button></div></form></div><div class="card section"><div class="section-head"><h2>Security model</h2><span class="badge available">deny by default</span></div><div class="kv"><span>Grant source</span><strong>Human / Control Center</strong></div><div class="kv"><span>Maximum finite TTL</span><strong>150 days</strong></div><div class="kv"><span>No expiry</span><strong>Supported / revocable</strong></div><div class="kv"><span>Scope</span><strong>Single project</strong></div><div class="kv"><span>Policy behavior</span><strong>Deny overrides session</strong></div></div></div><div class="card section" style="margin-top:16px"><div class="section-head"><h2>Project sessions</h2><span class="small">Expired/revoked sessions cannot authorize</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Principal</th><th>Capabilities</th><th>Expires</th><th>Status</th><th>Action</th></tr></thead><tbody id="sessionsBody"></tbody></table></div></div></section><section id="panel-policies" class="panel"><div class="grid split"><div class="card section"><div class="section-head"><h2>Create policy</h2><span class="badge available">P2-T04</span></div><form id="policyForm"><div class="form-grid"><div class="field full"><label>Name</label><input id="policyName" required placeholder="freeze-command-execution"></div><div class="field"><label>Scope</label><select id="policyProject"></select></div><div class="field"><label>Capability</label><select id="policyCapability"></select></div><div class="field"><label>Effect</label><select id="policyEffect"><option value="deny" selected>Deny</option><option value="allow">Allow / documentary</option></select></div><div class="field full"><label>Reason</label><input id="policyReason" placeholder="maintenance window"></div></div><div class="actions" style="justify-content:flex-end;margin-top:16px"><button class="btn primary" type="submit">Create policy</button></div></form></div><div class="card section"><div class="section-head"><h2>Evaluation order</h2><span class="badge available">deterministic</span></div><div class="kv"><span>1</span><strong>Project must be active</strong></div><div class="kv"><span>2</span><strong>Session must be active + project-bound</strong></div><div class="kv"><span>3</span><strong>Session must grant capability</strong></div><div class="kv"><span>4</span><strong>Any matching deny policy rejects</strong></div></div></div><div class="card section" style="margin-top:16px"><div class="section-head"><h2>Policies</h2><span class="small">Global + project scoped</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Policy</th><th>Scope</th><th>Capability</th><th>Effect</th><th>Status</th><th>Actions</th></tr></thead><tbody id="policiesBody"></tbody></table></div></div></section><section id="panel-jobs" class="panel"><div class="grid split"><div class="card section"><div class="section-head"><h2>Create persistent AI job</h2><span class="badge available">P7</span></div><div class="notice warn" style="margin-bottom:14px">Jobs persist objective/state/evidence but never persist permission-session IDs. Creation requires one active project session granting read + write + command.</div><form id="jobForm"><div class="form-grid"><div class="field full"><label>Project</label><select id="jobProject" required></select></div><div class="field full"><label>Objective</label><textarea id="jobObjective" maxlength="2000" required placeholder="Describe the coding outcome this job should drive..."></textarea></div><div class="field"><label>Maximum iterations</label><select id="jobMaxIterations"><option value="3">3</option><option value="5" selected>5</option><option value="8">8</option><option value="12">12</option><option value="20">20</option></select></div></div><div class="actions" style="justify-content:flex-end;margin-top:16px"><button class="btn primary" type="submit">Create AI job</button></div></form></div><div class="card section"><div class="section-head"><h2>State machine</h2><span class="badge available">persistent</span></div><div class="kv"><span>Queued</span><strong>Ready for first coding cycle</strong></div><div class="kv"><span>Awaiting fix</span><strong>Verification failed; correction required</strong></div><div class="kv"><span>Awaiting review</span><strong>Verification passed; semantic review required</strong></div><div class="kv"><span>Terminal</span><strong>Completed / stopped / failed / cancelled</strong></div></div></div><div class="card section" style="margin-top:16px"><div class="section-head"><h2>AI Jobs</h2><span class="small">SQLite-backed • restart-safe</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Objective</th><th>Status</th><th>Iteration</th><th>Evidence</th><th>Updated</th><th>Action</th></tr></thead><tbody id="jobsBody"></tbody></table></div></div></section><section id="panel-workflows" class="panel"><div class="card section"><div class="section-head"><div><h2>Workflow Runs</h2><div class="small">Derived directly from persistent AI job state/evidence</div></div><div class="field" style="min-width:260px"><label>Project</label><select id="workflowProject"></select></div></div><div id="workflowMetrics" class="grid metrics"></div><div class="table-wrap"><table class="table"><thead><tr><th>Objective</th><th>Status</th><th>Iteration</th><th>Next action</th><th>Review</th><th>Updated</th></tr></thead><tbody id="workflowBody"></tbody></table></div></div></section><section id="panel-git" class="panel"><div class="grid split"><div class="card section"><div class="section-head"><h2>Git repository</h2><button id="gitRefresh" class="btn" type="button">Refresh Git</button></div><div class="field"><label>Project</label><select id="gitProject"></select></div><div id="gitSummary" style="margin-top:14px"></div><div class="notice" style="margin-top:14px">Control Center is read-only for Git. Branch/stage/commit/restore mutations are exposed through permission-gated MCP tools; remote push remains a separate explicit action.</div></div><div class="card section"><div class="section-head"><h2>Local branches</h2><span class="small">Repository root must match project root</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Branch</th><th>State</th><th>Commit</th><th>Upstream</th></tr></thead><tbody id="gitBranchesBody"></tbody></table></div></div></div><div class="card section" style="margin-top:16px"><div class="section-head"><h2>Recent commits</h2><span class="small">Local history only</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Subject</th><th>Commit</th><th>Author</th><th>Authored</th></tr></thead><tbody id="gitCommitsBody"></tbody></table></div></div></section><section id="panel-processes" class="panel"><div class="grid split"><div class="card section"><div class="section-head"><h2>Managed process control</h2><button id="processRefresh" class="btn" type="button">Refresh</button></div><div class="form-grid"><div class="field full"><label>Project</label><select id="processProject"></select></div><div class="field full"><label>Process profile</label><select id="processProfile"></select><div id="processProfileHint" class="small"></div></div></div><div class="actions" style="justify-content:flex-end;margin-top:16px"><button id="startProcess" class="btn primary" type="button">Start process</button></div><div class="notice warn" style="margin-top:14px">Only discovered dev/start/serve/preview/storybook/watch package scripts can run. The agent cannot provide an arbitrary shell command.</div></div><div class="card section"><div class="section-head"><h2>Lifecycle contract</h2><span class="badge available">runtime-owned</span></div><div class="kv"><span>Environment</span><strong>sanitized</strong></div><div class="kv"><span>Logs</span><strong>bounded + redacted</strong></div><div class="kv"><span>Stop</span><strong>process-tree cleanup</strong></div><div class="kv"><span>Scope</span><strong>single registered project</strong></div></div></div><div class="card section" style="margin-top:16px"><div class="section-head"><h2>Process sessions</h2><span class="small">Current runtime only</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Profile</th><th>PID</th><th>Status</th><th>Started</th><th>Exit</th><th>Recent logs</th><th>Action</th></tr></thead><tbody id="processesBody"></tbody></table></div></div></section><section id="panel-browser" class="panel"><div class="grid split"><div class="card section"><div class="section-head"><h2>Preview control</h2><span class="badge available">loopback only</span></div><div class="form-grid"><div class="field full"><label>Project</label><select id="previewProject"></select></div><div class="field"><label>Preview profile</label><select id="previewProfile"></select><div id="previewProfileHint" class="small"></div></div><div class="field"><label>Browser review path</label><input id="previewPath" value="/" placeholder="/"></div></div><div class="actions" style="justify-content:flex-end;margin-top:16px"><button id="startPreview" class="btn primary" type="button">Start preview</button></div><div class="notice warn" style="margin-top:14px">Preview URLs are loopback-only. Browser Review accepts only a server-created preview session and blocks cross-origin page traffic.</div></div><div class="card section"><div class="section-head"><h2>Browser QA contract</h2><span class="badge available">Playwright + Edge/Chrome</span></div><div class="kv"><span>Navigation</span><strong>preview_id + relative path only</strong></div><div class="kv"><span>Network</span><strong>same-origin HTTP/WebSocket</strong></div><div class="kv"><span>Evidence</span><strong>DOM · console · requests · screenshot</strong></div><div class="kv"><span>Lifecycle</span><strong>runtime-owned start / status / stop</strong></div></div></div><div class="card section" style="margin-top:16px"><div class="section-head"><h2>Preview sessions</h2><span class="small">Current runtime only</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Profile</th><th>Kind</th><th>Status</th><th>URL</th><th>Port</th><th>Started</th><th>Actions</th></tr></thead><tbody id="previewsBody"></tbody></table></div></div><div class="card section" style="margin-top:16px"><div class="section-head"><h2>Browser Review evidence</h2><span class="small">Latest captured review</span></div><div id="previewEvidence"></div></div></section><section id="panel-tunnel" class="panel"><div class="grid split"><div id="tunnelSummary" class="card section"><div class="empty">Tunnel status is loading.</div></div><div class="card section"><div class="section-head"><h2>Managed runtime</h2><span class="badge available">official client</span></div><div id="tunnelRuntime"></div></div></div><div class="grid split" style="margin-top:16px"><div class="card section"><div class="section-head"><h2>One-time secure setup</h2><span class="badge available">Windows DPAPI</span></div><div class="notice">The Runtime API key is accepted only by this localhost form, encrypted with Windows DPAPI for the current Windows user, never stored in SQLite/plaintext, and never returned by the API.</div><form id="tunnelSetupForm" style="margin-top:14px"><div class="form-grid"><div class="field full"><label>Tunnel ID</label><input id="tunnelSetupId" required placeholder="tunnel_..."></div><div class="field full"><label>Runtime API key</label><input id="tunnelSetupKey" type="password" autocomplete="new-password" placeholder="Leave blank to keep the stored key"><div id="tunnelStoredSecret" class="small">Not stored yet</div></div><div class="field full"><label class="cap"><input id="tunnelSetupAuto" type="checkbox" checked> Auto-connect tunnel whenever MCP Coding starts</label></div><div class="field full"><label class="cap"><input id="tunnelWindowsAutoStart" type="checkbox"> Start MCP Coding automatically when I sign in to Windows</label><div id="tunnelAutoStartStatus" class="small">Windows auto-start status loading…</div></div></div><div class="actions" style="justify-content:flex-end;margin-top:14px"><button id="tunnelClearKey" class="btn danger" type="button">Remove stored key</button><button class="btn primary" type="submit">Save secure setup</button></div></form><div class="section-head" style="margin-top:20px"><h2>Operations</h2><span class="small">runtime control</span></div><div class="actions" style="margin-top:16px"><button id="tunnelRefresh" class="btn" type="button">Refresh status</button><button id="tunnelDoctorBtn" class="btn" type="button">Doctor</button><button id="tunnelConnectBtn" class="btn primary" type="button">Connect</button><button id="tunnelStopBtn" class="btn danger" type="button">Stop</button></div><div id="tunnelDoctor" class="evidence" style="margin-top:14px">No doctor run yet.</div></div><div class="card section"><div class="section-head"><h2>External activation</h2><span class="badge in_development">OpenAI account</span></div><div class="kv"><span>1</span><strong><a href="https://platform.openai.com/settings/organization/tunnels" target="_blank" rel="noopener noreferrer">Create tunnel</a></strong></div><div class="kv"><span>2</span><strong><a href="https://platform.openai.com/settings/organization/api-keys" target="_blank" rel="noopener noreferrer">Create runtime API key</a></strong></div><div class="kv"><span>3</span><strong><a href="https://chatgpt.com/#settings/Connectors" target="_blank" rel="noopener noreferrer">Configure ChatGPT connector</a></strong></div><div class="notice" style="margin-top:12px">Transport activation does not bypass project permission sessions or deny policies.</div></div></div></section><section id="panel-audit" class="panel"><div class="card section"><div class="section-head"><div><h2>Persistent audit log</h2><div class="small">MCP tool calls + mutating localhost Control Center APIs. Request bodies, prompts, file contents and secrets are not stored.</div></div><button id="auditRefresh" class="btn" type="button">Refresh audit</button></div><div class="form-grid" style="margin-bottom:16px"><div class="field"><label>Project</label><select id="auditProject"></select></div><div class="field"><label>Status</label><select id="auditStatus"><option value="">All statuses</option><option value="success">Success</option><option value="failure">Failure</option></select></div><div class="field"><label>Category</label><select id="auditCategory"><option value="">All categories</option><option value="mcp_tool">MCP tool</option><option value="control_center_api">Control Center API</option></select></div><div class="field"><label>Search action / actor / resource / error</label><input id="auditQuery" placeholder="write_file, HTTP_403, ..."></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Time</th><th>Category</th><th>Action</th><th>Project</th><th>Actor</th><th>Status</th><th>Duration</th><th>Error</th></tr></thead><tbody id="auditBody"></tbody></table></div></div></section><section id="panel-usage" class="panel"><div class="card section"><div class="section-head"><div><h2>Usage accounting</h2><div class="small">Known provider token usage and MCP activity in one persistent ledger</div></div><button id="usageRefresh" class="btn" type="button">Refresh usage</button></div><div class="form-grid" style="margin-bottom:16px"><div class="field"><label>Project</label><select id="usageProject"></select></div><div class="field"><label>Window</label><select id="usageDays"><option value="7">7 days</option><option value="30" selected>30 days</option><option value="90">90 days</option><option value="365">365 days</option></select></div></div><div id="usageVisibility" class="notice warn" style="margin-bottom:16px"></div><div id="usageMetrics" class="grid metrics"></div></div><div class="grid split" style="margin-top:16px"><div class="card section"><div class="section-head"><h2>LLM by provider / model</h2><span class="small">actual or explicitly estimated usage only</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Provider</th><th>Model</th><th>Requests</th><th>Tokens</th><th>Cost</th></tr></thead><tbody id="usageModelsBody"></tbody></table></div></div><div class="card section"><div class="section-head"><h2>Daily usage</h2><span class="small">request and token trend</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Day</th><th>Requests</th><th>Tool calls</th><th>Known tokens</th></tr></thead><tbody id="usageDailyBody"></tbody></table></div></div></div><div class="card section" style="margin-top:16px"><div class="section-head"><h2>Recent usage ledger</h2><span class="small">token visibility is explicit per event</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Time</th><th>Source</th><th>Actor</th><th>Provider</th><th>Model</th><th>Operation</th><th>Visibility</th><th>Tokens</th></tr></thead><tbody id="usageRecentBody"></tbody></table></div></div></section><section id="panel-settings" class="panel"><div class="card section"><div class="section-head"><h2>Effective runtime settings</h2><span class="small">Environment-backed</span></div><div id="settings"></div></div></section></main></div><div id="projectModal" class="modal"><div class="card modal-card"><div class="modal-title"><h2 id="modalHeading">Register project</h2><button id="closeModal" class="btn">Close</button></div><form id="projectForm"><div class="form-grid"><div class="field"><label>Name</label><input id="projectName" required maxlength="160"></div><div class="field"><label>Alias</label><input id="projectAlias" required maxlength="80" placeholder="my-project"></div><div class="field full"><label>Root path</label><input id="projectRoot" required maxlength="4096" placeholder="E:\\projects\\my-app"></div><div class="field"><label>Default branch</label><input id="projectBranch" placeholder="main"></div><div class="field"><label>Remote repository</label><input id="projectRemote" placeholder="optional"></div><div id="projectStatusField" class="field" style="display:none"><label>Status</label><select id="projectStatus"><option value="active">Active</option><option value="inactive">Inactive</option></select></div></div><div class="actions" style="justify-content:flex-end;margin-top:18px"><button id="cancelModal" type="button" class="btn">Cancel</button><button type="submit" class="btn primary">Save project</button></div></form></div></div><div id="toast" class="toast"></div><script src="/control-center/app.js"></script></body></html>`;
